create function public.studio_publish_cover(p_id uuid) returns uuid language plpgsql security invoker set search_path='' as $$ declare s text; begin if not exists(select 1 from public.studio_admin_memberships where user_id=(select auth.uid())) then raise exception 'Not authorized'; end if; select slot into s from public.studio_media where id=p_id and placement='cover' and mime_type in ('image/jpeg','image/png','image/webp'); if not found then raise exception 'Cover not found'; end if; perform pg_catalog.pg_advisory_xact_lock(pg_catalog.hashtext('bds-cover:'||s)); update public.studio_media set published=false where slot=s and placement='cover' and published and id<>p_id; update public.studio_media set published=true where id=p_id and slot=s and placement='cover'; if not found then raise exception 'Cover changed'; end if; return p_id; end; $$; revoke all on function public.studio_publish_cover(uuid) from public,anon; grant execute on function public.studio_publish_cover(uuid) to authenticated; create policy bds_media_admin_delete_draft on storage.objects for delete to authenticated using(bucket_id='bds-media' and exists(select 1 from public.studio_admin_memberships where user_id=(select auth.uid())) and not exists(select 1 from public.studio_media m where m.object_path=storage.objects.name and m.published));
